int binarySearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target)
            return mid;
        else if (arr[mid] < target)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return -1;
}

bool isBalanced(char* exp) {
    char stack[100];
    int top = -1;
    for(int i = 0; exp[i] != '\0'; i++) {
        char ch = exp[i];
        if (ch == '(' || ch == '{' || ch == '[') {
            stack[++top] = ch;
        } else if (ch == ')' || ch == '}' || ch == ']') {
            if (top == -1) return false;
            char popped = stack[top--];
            if (ch == ')' && popped != '(') return false;
            if (ch == '}' && popped != '{') return false;
            if (ch == ']' && popped != '[') return false;
        }
    }
    return (top == -1);
}

